import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.qcK96eCy.js";import"./chunks/assets.CGKUPeQw.js";var i=JSON.parse(`{"title":"AireFrame Release Notes","description":"","frontmatter":{},"headers":[],"relativePath":"aireblock-releases/AireFrame/aireframe-v3-3-0.md","filePath":"aireblock-releases/AireFrame/aireframe-v3-3-0.md","lastUpdated":1790237058000}`),a={name:`aireblock-releases/AireFrame/aireframe-v3-3-0.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="aireframe-release-notes" tabindex="-1"><span class="fsc-product"><img src="/aireframe-icon.png"> AireFrame Release Notes</span> <a class="header-anchor" href="#aireframe-release-notes" aria-label="Permalink to “AireFrame Release Notes”">​</a></h1><blockquote><p><strong>Version:</strong> v3.3.0<br><strong>Release Date:</strong> 23 September 2026</p></blockquote><h4 id="✨-new-features" tabindex="-1">✨ New Features <a class="header-anchor" href="#✨-new-features" aria-label="Permalink to “✨ New Features”">​</a></h4><ul><li>Ad-Hoc Form Submission in the Subject Portal (FRAME-2571)</li><li>Configurable Forms for the Portal (FRAME-2606)</li><li>Git Repository Support for Portal Form Configuration (FRAME-2666)</li><li>Secured Portal Form Creation (FRAME-2608)</li><li>Customisable Default Sort for Subject Lists (FRAME-2683)</li><li>Correlation ID Support for Building Block Data Sets (FRAME-2692)</li></ul><h4 id="⚡-improvements" tabindex="-1">⚡ Improvements <a class="header-anchor" href="#⚡-improvements" aria-label="Permalink to “⚡ Improvements”">​</a></h4><ul><li>Smarter Liquid Expression Type Checking (FRAME-1862)</li><li>Improved Dashboard Configuration Page (FRAME-2471)</li><li>Quick Links to Data Pipelines and Data Sets (FRAME-2661)</li><li>Tenant Name in Portal Header (FRAME-2695)</li></ul><h4 id="🐞-bug-fixes" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h4><ul><li>Improved Visibility of Subject Assignments in Nested Structures (FRAME-2530)</li><li>Fixed Swapped Fields in Location Providers Config Export/Import (FRAME-2688)</li><li>Fixed Page Styling for Long Custom Field Names (FRAME-2698)</li></ul><h1 id="detailed-changes" tabindex="-1">Detailed Changes <a class="header-anchor" href="#detailed-changes" aria-label="Permalink to “Detailed Changes”">​</a></h1><h3 id="✨-new-features-1" tabindex="-1">✨ New Features <a class="header-anchor" href="#✨-new-features-1" aria-label="Permalink to “✨ New Features”">​</a></h3><hr><h4 id="ad-hoc-form-submission-in-the-subject-portal-frame-2571" tabindex="-1">Ad-Hoc Form Submission in the Subject Portal (FRAME-2571) <a class="header-anchor" href="#ad-hoc-form-submission-in-the-subject-portal-frame-2571" aria-label="Permalink to “Ad-Hoc Form Submission in the Subject Portal (FRAME-2571)”">​</a></h4><div class="info custom-block"><p class="custom-block-title">Description</p><p>Portal users can now initiate and submit forms ad-hoc, without needing a form task first, using the same &quot;+&quot; button pattern already available in the clinician view. Availability can be gated by permission and tenant.</p></div><div class="tip custom-block"><p class="custom-block-title">What this means for you</p><p>If you use the portal, you can start and complete an available form yourself whenever you need to, rather than waiting for someone to send you a form task first.</p></div><h4 id="configurable-form-types-for-the-portal-frame-2606" tabindex="-1">Configurable Form Types for the Portal (FRAME-2606) <a class="header-anchor" href="#configurable-form-types-for-the-portal-frame-2606" aria-label="Permalink to “Configurable Form Types for the Portal (FRAME-2606)”">​</a></h4><div class="info custom-block"><p class="custom-block-title">Description</p><p>Tenant configurators can now select one or more form keys to control which forms are available for ad-hoc creation.</p></div><div class="tip custom-block"><p class="custom-block-title">What this means for you</p><p>As a configurator, you can decide exactly which forms your portal users are allowed to create themselves.</p></div><h4 id="git-repository-support-for-portal-form-configuration-frame-2666" tabindex="-1">Git Repository Support for Portal Form Configuration (FRAME-2666) <a class="header-anchor" href="#git-repository-support-for-portal-form-configuration-frame-2666" aria-label="Permalink to “Git Repository Support for Portal Form Configuration (FRAME-2666)”">​</a></h4><div class="info custom-block"><p class="custom-block-title">Description</p><p>Allowed portal form configuration can now also be managed via Git-based configuration, alongside the existing options.</p></div><div class="tip custom-block"><p class="custom-block-title">What this means for you</p><p>Portal form availability can be configured and version-controlled the same way as your other Git-managed configuration.</p></div><h4 id="customisable-default-sort-for-subject-lists-frame-2683" tabindex="-1">Customisable Default Sort for Subject Lists (FRAME-2683) <a class="header-anchor" href="#customisable-default-sort-for-subject-lists-frame-2683" aria-label="Permalink to “Customisable Default Sort for Subject Lists (FRAME-2683)”">​</a></h4><div class="info custom-block"><p class="custom-block-title">Description</p><p>Subject lists can now be configured with a default sort order, instead of always defaulting to newest subject first.</p></div><div class="tip custom-block"><p class="custom-block-title">What this means for you</p><p>When configuring a subject list, you can choose which field it&#39;s sorted by and in which direction - so the most relevant subjects appear first, not just the most recently created ones. Note that sorting by a field will hide subjects that don&#39;t have any data for that list.</p></div><h4 id="correlation-id-support-for-building-block-data-sets-frame-2692" tabindex="-1">Correlation ID Support for Building Block Data Sets (FRAME-2692) <a class="header-anchor" href="#correlation-id-support-for-building-block-data-sets-frame-2692" aria-label="Permalink to “Correlation ID Support for Building Block Data Sets (FRAME-2692)”">​</a></h4><div class="info custom-block"><p class="custom-block-title">Description</p><p>Building block data sets linked to another data set by correlation ID, which was previously unavailable because the building block had no knowledge of it.</p></div><div class="tip custom-block"><p class="custom-block-title">What this means for you</p><p>Grouping by correlation ID now works correctly when a building block data set is linked to another data set.</p></div><h3 id="⚡-improvements-1" tabindex="-1">⚡ Improvements <a class="header-anchor" href="#⚡-improvements-1" aria-label="Permalink to “⚡ Improvements”">​</a></h3><hr><h4 id="smarter-liquid-expression-type-checking-frame-1862" tabindex="-1">Smarter Liquid Expression Type Checking (FRAME-1862) <a class="header-anchor" href="#smarter-liquid-expression-type-checking-frame-1862" aria-label="Permalink to “Smarter Liquid Expression Type Checking (FRAME-1862)”">​</a></h4><div class="info custom-block"><p class="custom-block-title">Description</p><p>Liquid expressions that branch with <code>if</code> / <code>elsif</code> / <code>else</code> now have their output data type correctly determined based on what each branch produces. Previously, any expression using <code>elsif</code> or <code>else</code> was always treated as producing a text (string) result, even if every branch clearly produced a number, date, or true/false value. Now, if all branches agree on the same type, that type is used.</p></div><div class="tip custom-block"><p class="custom-block-title">What this means for you</p><p>Liquid expressions like category or score lookups (for example, mapping a status to a numeric code across several <code>if</code> / <code>elsif</code> / <code>else</code> branches) can now correctly produce a number, decimal, date, or boolean field — instead of always being forced into a text field. This removes the need for workarounds when building this kind of expression.</p></div><h4 id="improved-dashboard-configuration-page-frame-2471" tabindex="-1">Improved Dashboard Configuration Page (FRAME-2471) <a class="header-anchor" href="#improved-dashboard-configuration-page-frame-2471" aria-label="Permalink to “Improved Dashboard Configuration Page (FRAME-2471)”">​</a></h4><div class="info custom-block"><p class="custom-block-title">Description</p><p>The dashboard configuration page has been brought in line with the widgets, pipelines and data sets pages: dashboards are shown in a searchable table, and clicking a row opens a dedicated configuration page for that dashboard.</p></div><div class="tip custom-block"><p class="custom-block-title">What this means for you</p><p>Finding and configuring a dashboard is easier: you can search the list and click straight into the one you want, the same way you already can for widgets, pipelines and data sets.</p></div><h4 id="quick-links-to-data-pipelines-and-data-sets-frame-2661" tabindex="-1">Quick Links to Data Pipelines and Data Sets (FRAME-2661) <a class="header-anchor" href="#quick-links-to-data-pipelines-and-data-sets-frame-2661" aria-label="Permalink to “Quick Links to Data Pipelines and Data Sets (FRAME-2661)”">​</a></h4><div class="info custom-block"><p class="custom-block-title">Description</p><p>Configuration pages now include a link icon that opens the related data pipeline or data set directly in a new tab, rather than requiring separate navigation through the configuration screens.</p></div><div class="tip custom-block"><p class="custom-block-title">What this means for you</p><p>You can jump straight to a linked data pipeline or data set from a configuration page, without hunting through menus.</p></div><h4 id="tenant-name-in-portal-header-frame-2695" tabindex="-1">Tenant Name in Portal Header (FRAME-2695) <a class="header-anchor" href="#tenant-name-in-portal-header-frame-2695" aria-label="Permalink to “Tenant Name in Portal Header (FRAME-2695)”">​</a></h4><div class="info custom-block"><p class="custom-block-title">Description</p><p>The AireFrame Portal header now shows the tenant name, matching the existing behaviour in AireFrame.</p></div><div class="tip custom-block"><p class="custom-block-title">What this means for you</p><p>You&#39;ll see which tenant you&#39;re working in directly in the portal header, just as you already can in AireFrame.</p></div><h3 id="🐞-bug-fixes-1" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes-1" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h3><hr><h4 id="improved-visibility-of-subject-assignments-in-nested-structures-frame-2530" tabindex="-1">Improved Visibility of Subject Assignments in Nested Structures (FRAME-2530) <a class="header-anchor" href="#improved-visibility-of-subject-assignments-in-nested-structures-frame-2530" aria-label="Permalink to “Improved Visibility of Subject Assignments in Nested Structures (FRAME-2530)”">​</a></h4><div class="info custom-block"><p class="custom-block-title">Description</p><p>Where a subject was assigned deep within a nested structure, there was no way to see this in the UI, which could make it look as though the subject wasn&#39;t assigned at all. The nested structure now expands to show the location the subject is assigned to.</p></div><h4 id="fixed-swapped-fields-in-location-providers-config-export-import-frame-2688" tabindex="-1">Fixed Swapped Fields in Location Providers Config Export/Import (FRAME-2688) <a class="header-anchor" href="#fixed-swapped-fields-in-location-providers-config-export-import-frame-2688" aria-label="Permalink to “Fixed Swapped Fields in Location Providers Config Export/Import (FRAME-2688)”">​</a></h4><div class="info custom-block"><p class="custom-block-title">Description</p><p>When an Upsert API location providers configuration was exported and then re-imported, certain fields were incorrectly swapped. This has been fixed so exported configuration re-imports correctly.</p></div><h4 id="fixed-page-styling-for-long-custom-field-names-frame-2698" tabindex="-1">Fixed Page Styling for Long Custom Field Names (FRAME-2698) <a class="header-anchor" href="#fixed-page-styling-for-long-custom-field-names-frame-2698" aria-label="Permalink to “Fixed Page Styling for Long Custom Field Names (FRAME-2698)”">​</a></h4><div class="info custom-block"><p class="custom-block-title">Description</p><p>Long custom field names could break the page&#39;s styling on the custom field configuration page. Long names are now handled gracefully without disrupting the layout.</p></div>`,48)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};